/bin/bash -lc "python3 - <<'PY'
import subprocess, re
manifest='/mnt/data/LSF/results/court/agentic_rule_full_data_gpt54mini_adaptive/all_docs/q11_who_is_the_firstlisted_attorney_representing_the_appellants.manifest.json'
doc='20250723_state_of_washington_v._trump'
txt=subprocess.check_output(['python3','src/baseline/agentic_rule_full_data.py','read-doc-txt','--manifest',manifest,'--doc-name',doc], text=True)
lines=[{'page_no':None,'line_no':i,'text':l} for i,l in enumerate(txt.splitlines(),1)]

def norm(value):
    return re.sub(r'\\s+',' ', value or '').strip()

def is_section_boundary(text):
    upper=text.upper()
    if upper in {'COUNSEL','OPINION','SUMMARY','ORDER'}:
        return True
    return bool(re.match(r'(?i)"'^(before:|appeal from|argued and submitted|submitted|filed|no'"\\.\\s|d\\.c\\.\\s+no\\.)', text))

# caption labels
caption_lines=[]
for line in lines[:150]:
    text=norm(line.get('text',''))
    if text:
        caption_lines.append(text)
labels=[]
for text in caption_lines:
    lowered=text.lower()
    if 'appellant' not in lowered:
        continue
    m=re.search(r'(?i)([A-Za-z][A-Za-z0-9 .&\\'/-]*?)\\s*(?:-\\s*|\\s*)appellant(?:s)?\\b', text)
    if not m:
        continue
    label=re.sub(r'\\s+',' ', m.group(1)).strip(' ,;:-')
    if label and label.lower() not in [e.lower() for e in labels]:
        labels.append(label)
print('labels', labels)
appellant_label_lowers=[label.lower() for label in labels]

def has_appellant_marker(text):
    lowered=text.lower()
    if 'for' not in lowered:
        return False
    if 'appellant' in lowered and 'appellee' not in lowered:
        return True
    return any(label in lowered for label in appellant_label_lowers)

def has_party_marker(text):
    lowered=text.lower()
    return 'for' in lowered and lowered.rstrip().endswith('.')

candidate_idxs=[]
for i,line in enumerate(lines[:120]):
    text=norm(line.get('text',''))
    if text and has_appellant_marker(text):
        candidate_idxs.append(i)
print('candidates', candidate_idxs[:10], [lines[i]['text'] for i in candidate_idxs[:5]])
for idx in candidate_idxs:
    print('trying idx', idx, lines[idx]['text'])
    seg_start=0
    for j in range(idx-1,-1,-1):
        text=norm(lines[j].get('text',''))
        if not text:
            continue
        if has_party_marker(text):
            seg_start=j+1
            break
        if text.upper()=='COUNSEL' or is_section_boundary(text):
            seg_start=j+1
            break
    print('seg_start', seg_start, repr(lines[seg_start]['text']))
    while seg_start < idx and not norm(lines[seg_start].get('text','')):
        seg_start += 1
    start_text=norm(lines[seg_start].get('text',''))
    print('start_text', repr(start_text))
    name = re.split(r'\\s+and\\s+|;\\s+|,\\s+', start_text, 1)[0].strip()
    name = re.sub(r'\\s*\\(.*?\\)', '', name).strip(' ,;:-')
    print('name', repr(name), len(name.split()))
    if name and len(name.split()) >= 2:
        print('RETURN', name)
        break
PY"

